    /** Daftar produk milik satu seri (UUID). */
    export function getBatch4ProdukBySeriId(seriId: string): ProdukKomersialBatch4Item[] {
    return PK_BATCH4_PRODUK_LIST.filter(p => p.seriId === seriId);
    }

    /** Lookup satu produk via seriId + produkSlug (routing). */
    export function getBatch4ProdukBySlug(seriId: string, produkSlug: string): ProdukKomersialBatch4Item | undefined {
    return PK_BATCH4_PRODUK_LIST.find(p => p.seriId === seriId && p.slug === produkSlug);
    }

    /** Lookup produk via UUID. */
    export function getBatch4ProdukByUUID(uuid: string): ProdukKomersialBatch4Item | undefined {
    return PK_BATCH4_PRODUK_LIST.find(p => p.uuid === uuid);
    }

    /** Jumlah total produk pada satu kategori (slug). */
    export function getBatch4JumlahProdukByKategoriSlug(kategoriSlug: string): number {
    return PK_BATCH4_PRODUK_LIST.filter(p => p.kategoriSlug === kategoriSlug).length;
    }
    